#!/usr/bin/env python3
"""
Adds a custom video player (skip +/-10s, playback speed up to 2x,
scrub bar) to the movie detail page.

Usage (run from the project ROOT - the folder containing
'backend' and 'frontend'):

    cd mdm-project-main
    python apply_video_player_controls.py
"""

import os
import shutil
import sys

FILES = {}

FILES['frontend/components/movies/VideoPlayer.tsx'] = '\'use client\';\n\nimport { useEffect, useRef, useState } from \'react\';\nimport {\n  Pause,\n  Play,\n  RotateCcw,\n  RotateCw,\n  Volume2,\n  VolumeX,\n} from \'lucide-react\';\nimport { cn } from \'@/lib/utils\';\n\nconst SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 2] as const;\nconst SKIP_SECONDS = 10;\n\nfunction formatTime(seconds: number): string {\n  if (!Number.isFinite(seconds) || seconds < 0) return \'0:00\';\n  const total = Math.floor(seconds);\n  const h = Math.floor(total / 3600);\n  const m = Math.floor((total % 3600) / 60);\n  const s = total % 60;\n  const mm = h > 0 ? String(m).padStart(2, \'0\') : String(m);\n  const ss = String(s).padStart(2, \'0\');\n  return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;\n}\n\ninterface VideoPlayerProps {\n  src: string;\n  poster?: string;\n  className?: string;\n}\n\n/**\n * A movie player with the controls a native <video> element doesn\'t\n * reliably expose across browsers: skip back/forward 10s, a visible\n * playback-speed toggle (up to 2x), and a scrub bar to jump to any point.\n */\nexport function VideoPlayer({ src, poster, className }: VideoPlayerProps) {\n  const videoRef = useRef<HTMLVideoElement>(null);\n\n  const [isPlaying, setIsPlaying] = useState(false);\n  const [currentTime, setCurrentTime] = useState(0);\n  const [duration, setDuration] = useState(0);\n  const [speedIndex, setSpeedIndex] = useState(2); // 1x\n  const [isMuted, setIsMuted] = useState(false);\n  const [isScrubbing, setIsScrubbing] = useState(false);\n  const [scrubTime, setScrubTime] = useState(0);\n\n  const speed = SPEEDS[speedIndex];\n\n  useEffect(() => {\n    const video = videoRef.current;\n    if (!video) return;\n\n    const onTimeUpdate = () => {\n      if (!isScrubbing) setCurrentTime(video.currentTime);\n    };\n    const onLoadedMetadata = () => setDuration(video.duration);\n    const onPlay = () => setIsPlaying(true);\n    const onPause = () => setIsPlaying(false);\n    const onEnded = () => setIsPlaying(false);\n\n    video.addEventListener(\'timeupdate\', onTimeUpdate);\n    video.addEventListener(\'loadedmetadata\', onLoadedMetadata);\n    video.addEventListener(\'play\', onPlay);\n    video.addEventListener(\'pause\', onPause);\n    video.addEventListener(\'ended\', onEnded);\n\n    return () => {\n      video.removeEventListener(\'timeupdate\', onTimeUpdate);\n      video.removeEventListener(\'loadedmetadata\', onLoadedMetadata);\n      video.removeEventListener(\'play\', onPlay);\n      video.removeEventListener(\'pause\', onPause);\n      video.removeEventListener(\'ended\', onEnded);\n    };\n  }, [isScrubbing]);\n\n  useEffect(() => {\n    if (videoRef.current) videoRef.current.playbackRate = speed;\n  }, [speed]);\n\n  function togglePlay() {\n    const video = videoRef.current;\n    if (!video) return;\n    if (video.paused) video.play();\n    else video.pause();\n  }\n\n  function skip(deltaSeconds: number) {\n    const video = videoRef.current;\n    if (!video) return;\n    video.currentTime = Math.min(\n      Math.max(video.currentTime + deltaSeconds, 0),\n      duration || video.currentTime + deltaSeconds\n    );\n  }\n\n  function cycleSpeed() {\n    setSpeedIndex((i) => (i + 1) % SPEEDS.length);\n  }\n\n  function toggleMute() {\n    const video = videoRef.current;\n    if (!video) return;\n    video.muted = !video.muted;\n    setIsMuted(video.muted);\n  }\n\n  function handleScrubStart() {\n    setIsScrubbing(true);\n    setScrubTime(currentTime);\n  }\n\n  function handleScrubChange(e: React.ChangeEvent<HTMLInputElement>) {\n    setScrubTime(Number(e.target.value));\n  }\n\n  function handleScrubCommit() {\n    const video = videoRef.current;\n    if (video) video.currentTime = scrubTime;\n    setCurrentTime(scrubTime);\n    setIsScrubbing(false);\n  }\n\n  const displayedTime = isScrubbing ? scrubTime : currentTime;\n\n  return (\n    <div className={cn(\'group relative overflow-hidden rounded-xl bg-black\', className)}>\n      <video\n        ref={videoRef}\n        src={src}\n        poster={poster || undefined}\n        className="aspect-video w-full"\n        onClick={togglePlay}\n      >\n        Your browser doesn&apos;t support video playback.\n      </video>\n\n      {/* Center play/pause overlay, shown when paused or on hover */}\n      {!isPlaying && (\n        <button\n          type="button"\n          onClick={togglePlay}\n          aria-label="Play"\n          className="absolute inset-0 flex items-center justify-center bg-black/20 transition-colors hover:bg-black/30"\n        >\n          <span className="flex h-16 w-16 items-center justify-center rounded-full bg-white/90 text-black">\n            <Play size={28} className="ml-1 fill-current" />\n          </span>\n        </button>\n      )}\n\n      {/* Control bar */}\n      <div className="absolute inset-x-0 bottom-0 flex flex-col gap-1.5 bg-gradient-to-t from-black/85 via-black/50 to-transparent px-3 pb-2 pt-8">\n        <input\n          type="range"\n          min={0}\n          max={duration || 0}\n          step={0.1}\n          value={displayedTime}\n          onMouseDown={handleScrubStart}\n          onTouchStart={handleScrubStart}\n          onChange={handleScrubChange}\n          onMouseUp={handleScrubCommit}\n          onTouchEnd={handleScrubCommit}\n          aria-label="Seek"\n          className="video-scrub-bar h-1.5 w-full cursor-pointer appearance-none rounded-full bg-white/25 accent-accent"\n        />\n\n        <div className="flex items-center gap-3 text-white">\n          <button type="button" onClick={togglePlay} aria-label={isPlaying ? \'Pause\' : \'Play\'} className="hover:text-accent">\n            {isPlaying ? <Pause size={18} className="fill-current" /> : <Play size={18} className="fill-current" />}\n          </button>\n\n          <button type="button" onClick={() => skip(-SKIP_SECONDS)} aria-label={`Back ${SKIP_SECONDS} seconds`} className="hover:text-accent">\n            <RotateCcw size={17} />\n          </button>\n\n          <button type="button" onClick={() => skip(SKIP_SECONDS)} aria-label={`Forward ${SKIP_SECONDS} seconds`} className="hover:text-accent">\n            <RotateCw size={17} />\n          </button>\n\n          <button type="button" onClick={toggleMute} aria-label={isMuted ? \'Unmute\' : \'Mute\'} className="hover:text-accent">\n            {isMuted ? <VolumeX size={17} /> : <Volume2 size={17} />}\n          </button>\n\n          <span className="font-mono text-xs tabular-nums text-white/80">\n            {formatTime(displayedTime)} / {formatTime(duration)}\n          </span>\n\n          <button\n            type="button"\n            onClick={cycleSpeed}\n            aria-label="Playback speed"\n            className="ml-auto rounded border border-white/30 px-2 py-0.5 font-mono text-xs hover:border-accent hover:text-accent"\n          >\n            {speed}x\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n'

FILES['frontend/app/(app)/movies/[id]/page.tsx'] = '\'use client\';\n\nimport { use, useEffect, useState } from \'react\';\nimport Link from \'next/link\';\nimport Image from \'next/image\';\nimport { ArrowLeft, Heart, ListPlus, CheckCircle2, Bookmark, Star } from \'lucide-react\';\nimport { moviesApi, libraryApi } from \'@/lib/endpoints\';\nimport { useToast } from \'@/hooks/useToast\';\nimport { formatRuntime, formatYear, getErrorMessage } from \'@/lib/utils\';\nimport type { Movie } from \'@/types\';\nimport { Button } from \'@/components/ui/Button\';\nimport { StarRating } from \'@/components/ui/StarRating\';\nimport { Textarea } from \'@/components/ui/Input\';\nimport { AddToPlaylistModal } from \'@/components/playlists/AddToPlaylistModal\';\nimport { VideoPlayer } from \'@/components/movies/VideoPlayer\';\nimport { Skeleton } from \'@/components/ui/Skeleton\';\n\nexport default function MovieDetailPage({ params }: { params: Promise<{ id: string }> }) {\n  const { id } = use(params);\n  const movieId = Number(id);\n  const { showToast } = useToast();\n\n  const [movie, setMovie] = useState<Movie | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [playlistModalOpen, setPlaylistModalOpen] = useState(false);\n\n  const [isFavorited, setIsFavorited] = useState(false);\n  const [isWatched, setIsWatched] = useState(false);\n  const [isOnWatchlist, setIsOnWatchlist] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n\n  const [ratingScore, setRatingScore] = useState(0);\n  const [review, setReview] = useState(\'\');\n  const [savingRating, setSavingRating] = useState(false);\n\n  useEffect(() => {\n    let cancelled = false;\n    moviesApi\n      .detail(movieId)\n      .then((data) => {\n        if (cancelled) return;\n        setMovie(data);\n        setIsFavorited(data.is_favorited);\n        setIsWatched(data.is_watched);\n        setIsOnWatchlist(data.is_in_watchlist);\n        if (data.my_rating) {\n          setRatingScore(data.my_rating.score);\n          setReview(data.my_rating.review);\n        }\n      })\n      .catch((err) => !cancelled && setError(getErrorMessage(err)));\n    return () => {\n      cancelled = true;\n    };\n  }, [movieId]);\n\n  async function toggleFavorite() {\n    if (busy) return;\n    setBusy(\'favorite\');\n    const next = !isFavorited;\n    setIsFavorited(next);\n    try {\n      if (next) {\n        await libraryApi.addFavorite(movieId);\n      } else {\n        await libraryApi.removeFavorite(movieId);\n      }\n    } catch (err) {\n      setIsFavorited(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function toggleWatched() {\n    if (busy) return;\n    setBusy(\'watched\');\n    const next = !isWatched;\n    setIsWatched(next);\n    try {\n      if (next) {\n        await libraryApi.markWatched(movieId);\n      } else {\n        await libraryApi.markUnwatched(movieId);\n      }\n    } catch (err) {\n      setIsWatched(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function toggleWatchlist() {\n    if (busy) return;\n    setBusy(\'watchlist\');\n    const next = !isOnWatchlist;\n    setIsOnWatchlist(next);\n    try {\n      if (next) {\n        await libraryApi.addToWatchlist(movieId);\n      } else {\n        await libraryApi.removeFromWatchlist(movieId);\n      }\n    } catch (err) {\n      setIsOnWatchlist(!next);\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function saveRating() {\n    if (ratingScore === 0) {\n      showToast(\'Pick a star rating first.\', \'error\');\n      return;\n    }\n    setSavingRating(true);\n    try {\n      await libraryApi.rateMovie(movieId, { score: ratingScore, review });\n      showToast(\'Rating saved.\', \'success\');\n    } catch (err) {\n      showToast(getErrorMessage(err), \'error\');\n    } finally {\n      setSavingRating(false);\n    }\n  }\n\n  if (error) {\n    return (\n      <div className="mx-auto max-w-4xl">\n        <p className="rounded-lg border border-danger/30 bg-danger/10 px-4 py-3 text-sm text-danger">{error}</p>\n      </div>\n    );\n  }\n\n  if (!movie) {\n    return (\n      <div className="mx-auto max-w-5xl">\n        <Skeleton className="h-64 w-full" />\n        <div className="mt-6 flex gap-6">\n          <Skeleton className="h-72 w-48 shrink-0" />\n          <div className="flex-1 space-y-3">\n            <Skeleton className="h-8 w-2/3" />\n            <Skeleton className="h-4 w-1/3" />\n            <Skeleton className="h-24 w-full" />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className="mx-auto max-w-5xl pb-16">\n      <Link href="/movies" className="inline-flex items-center gap-1.5 text-sm text-foreground-muted hover:text-foreground">\n        <ArrowLeft size={15} /> Back to movies\n      </Link>\n\n      {/* Player (for a movie you uploaded yourself) or backdrop */}\n      {movie.video_file ? (\n        <VideoPlayer\n          src={movie.video_file}\n          poster={movie.poster_url || undefined}\n          className="mt-4 w-full"\n        />\n      ) : (\n        <div className="relative mt-4 aspect-[21/9] w-full overflow-hidden rounded-xl bg-surface">\n          {movie.backdrop_url ? (\n            <Image src={movie.backdrop_url} alt="" fill sizes="100vw" className="object-cover" priority />\n          ) : null}\n          <div className="absolute inset-0 bg-gradient-to-t from-background via-background/40 to-transparent" />\n        </div>\n      )}\n\n      <div\n        className={`flex flex-col gap-6 px-2 sm:flex-row sm:px-4 ${\n          movie.video_file ? \'mt-6\' : \'-mt-20\'\n        }`}\n      >\n        {/* Poster */}\n        <div className="relative aspect-[2/3] w-40 shrink-0 overflow-hidden rounded-lg border border-border bg-surface shadow-xl sm:w-52">\n          {movie.poster_url ? (\n            <Image src={movie.poster_url} alt={movie.title} fill sizes="208px" className="object-cover" />\n          ) : (\n            <div className="flex h-full items-center justify-center text-xs text-foreground-muted">No poster</div>\n          )}\n        </div>\n\n        <div className="flex-1 pt-2 sm:pt-16">\n          <h1 className="font-display text-2xl font-medium text-foreground sm:text-3xl">{movie.title}</h1>\n          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 font-mono text-sm text-foreground-muted">\n            <span>{formatYear(movie.release_date)}</span>\n            <span>•</span>\n            <span>{formatRuntime(movie.runtime_minutes)}</span>\n            {movie.genres.length > 0 && (\n              <>\n                <span>•</span>\n                <span>{movie.genres.map((g) => g.name).join(\' / \')}</span>\n              </>\n            )}\n            {movie.rating && (\n              <>\n                <span>•</span>\n                <span className="flex items-center gap-1 text-warning">\n                  <Star size={13} className="fill-warning" /> {movie.rating}\n                </span>\n              </>\n            )}\n          </div>\n\n          {movie.description && <p className="mt-4 max-w-2xl text-sm leading-relaxed text-foreground-muted">{movie.description}</p>}\n\n          {movie.director && <p className="mt-4 text-sm text-foreground">\n            <span className="text-foreground-muted">Director: </span>{movie.director.name}\n          </p>}\n\n          {movie.cast_members && movie.cast_members.length > 0 && (\n            <div className="mt-2 text-sm text-foreground">\n              <span className="text-foreground-muted">Cast: </span>\n              {movie.cast_members\n                .slice()\n                .sort((a, b) => a.billing_order - b.billing_order)\n                .map((c) => c.name)\n                .join(\', \')}\n            </div>\n          )}\n\n          <div className="mt-6 flex flex-wrap gap-2">\n            <Button\n              variant={isWatched ? \'primary\' : \'secondary\'}\n              onClick={toggleWatched}\n              isLoading={busy === \'watched\'}\n            >\n              <CheckCircle2 size={16} /> {isWatched ? \'Watched\' : \'Mark watched\'}\n            </Button>\n            <Button\n              variant={isOnWatchlist ? \'primary\' : \'secondary\'}\n              onClick={toggleWatchlist}\n              isLoading={busy === \'watchlist\'}\n            >\n              <Bookmark size={16} /> {isOnWatchlist ? \'On watchlist\' : \'Add to watchlist\'}\n            </Button>\n            <Button variant="secondary" onClick={() => setPlaylistModalOpen(true)}>\n              <ListPlus size={16} /> Add to playlist\n            </Button>\n            <Button\n              variant={isFavorited ? \'primary\' : \'secondary\'}\n              onClick={toggleFavorite}\n              isLoading={busy === \'favorite\'}\n            >\n              <Heart size={16} className={isFavorited ? \'fill-current\' : \'\'} /> Favorite\n            </Button>\n          </div>\n        </div>\n      </div>\n\n      {/* Personal rating + review */}\n      <div className="mt-10 max-w-2xl rounded-xl border border-border bg-surface p-5">\n        <h2 className="font-display text-lg font-medium text-foreground">Your rating</h2>\n        <div className="mt-3">\n          <StarRating value={ratingScore} onChange={setRatingScore} />\n        </div>\n        <Textarea\n          label="Your review"\n          value={review}\n          onChange={(e) => setReview(e.target.value)}\n          placeholder="What did you think?"\n          rows={3}\n          className="mt-4"\n        />\n        <Button className="mt-3" onClick={saveRating} isLoading={savingRating}>\n          Save review\n        </Button>\n      </div>\n\n      <AddToPlaylistModal\n        isOpen={playlistModalOpen}\n        onClose={() => setPlaylistModalOpen(false)}\n        movieId={movie.id}\n        movieTitle={movie.title}\n      />\n    </div>\n  );\n}\n'

def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, 'backend')) or not os.path.isdir(os.path.join(root, 'frontend')):
        print('Error: run this script from the project root (must contain backend/ and frontend/ folders).')
        sys.exit(1)

    print('Backing up files that will be changed (.bak)...')
    for rel_path in FILES:
        full_path = os.path.join(root, rel_path)
        if os.path.exists(full_path):
            shutil.copyfile(full_path, full_path + '.bak')

    for rel_path, content in FILES.items():
        full_path = os.path.join(root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        print(f'Writing {rel_path}...')
        with open(full_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)

    print()
    print('Done. Restart your frontend dev server (npm run dev) if it was already running.')
    print('Backups of the original files were saved alongside them as *.bak')

if __name__ == '__main__':
    main()
